// Generates src/styles/generated/tokens.css and tokens.ts from the DESIGN.md frontmatter (AD-11).
// DESIGN.md is the only source; never edit the generated files by hand.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const DESIGN_PATH = join(root, '_bmad-output/planning-artifacts/ux-designs/ux-Visual Math-2026-11-26/DESIGN.md');
export const OUT_DIR = join(root, 'src/styles/generated');

export function readDesign(path = DESIGN_PATH) {
  const text = readFileSync(path, 'utf8').replace(/^﻿/, '').replace(/\r\n/g, '\n');
  const m = /^---\n([\s\S]*?)\n---(?:\n|$)/.exec(text);
  if (!m) throw new Error('DESIGN.md has no frontmatter');
  return { fm: validate(parse(m[1])), body: text.slice(m[0].length) };
}

const HEX_VALUE = /^#[0-9A-Fa-f]{6}([0-9A-Fa-f]{2})?$/;
const TYPE_FIELDS = ['fontFamily', 'fontSize', 'fontWeight', 'lineHeight'];
// Roles that CSS written outside the generator relies on; a rename in DESIGN.md must fail here, not silently.
const REQUIRED_TYPES = ['body', 'urdu-body'];

/** Fails loudly on anything that would emit `undefined`, `null` or a non-color into the generated files. */
export function validate(fm) {
  for (const section of ['colors', 'typography', 'spacing', 'rounded']) {
    if (!fm?.[section] || typeof fm[section] !== 'object') throw new Error(`DESIGN.md frontmatter has no "${section}"`);
  }
  for (const [k, v] of Object.entries(fm.colors)) {
    if (typeof v !== 'string' || !HEX_VALUE.test(v)) throw new Error(`colors.${k} must be a quoted #RRGGBB or #RRGGBBAA value, got ${JSON.stringify(v)}`);
  }
  for (const [name, t] of Object.entries(fm.typography)) {
    for (const f of TYPE_FIELDS) {
      if (t?.[f] === undefined || t[f] === null) throw new Error(`typography.${name}.${f} is missing`);
    }
  }
  for (const need of REQUIRED_TYPES) {
    if (!fm.typography[need]) throw new Error(`typography.${need} is required`);
  }
  return fm;
}

/** Split `colors` into light roles and dark roles (keys ending in `-dark`). Throws if a twin is missing. */
export function splitColors(colors) {
  const light = {};
  const dark = {};
  for (const [k, v] of Object.entries(colors)) {
    if (k.endsWith('-dark')) dark[k.slice(0, -5)] = v;
    else light[k] = v;
  }
  const missing = Object.keys(light).filter((k) => !(k in dark));
  const extra = Object.keys(dark).filter((k) => !(k in light));
  if (missing.length || extra.length) {
    throw new Error(`colors need a light and a -dark value: missing dark for [${missing}], dark without light [${extra}]`);
  }
  return { light, dark };
}

const HEADER = '/* GENERATED by scripts/build-tokens.mjs from DESIGN.md. Do not edit. Run `npm run tokens`. */\n';
const cssVars = (obj, prefix, indent) => Object.entries(obj).map(([k, v]) => `${indent}--vm-${prefix}-${k}: ${v};`);

export function generate(fm) {
  const { light, dark } = splitColors(fm.colors);
  const type = [];
  for (const [name, t] of Object.entries(fm.typography)) {
    type.push(`  --vm-type-${name}-font: ${t.fontFamily};`, `  --vm-type-${name}-size: ${t.fontSize};`,
      `  --vm-type-${name}-weight: ${t.fontWeight};`, `  --vm-type-${name}-line: ${t.lineHeight};`);
  }
  const spacing = Object.fromEntries(Object.entries(fm.spacing).map(([k, v]) => [k, String(v)]));
  const rounded = Object.fromEntries(Object.entries(fm.rounded).map(([k, v]) => [k, String(v)]));

  const css = [
    HEADER,
    ':root {',
    ...cssVars(light, 'color', '  '),
    ...type,
    ...cssVars(spacing, 'space', '  '),
    ...cssVars(rounded, 'radius', '  '),
    '  color-scheme: light;',
    '}',
    '',
    ':root[data-theme="dark"] {',
    ...cssVars(dark, 'color', '  '),
    '  color-scheme: dark;',
    '}',
    '',
    '/* No JavaScript: follow the operating system. The pre-paint script sets data-theme, which wins. */',
    '@media (prefers-color-scheme: dark) {',
    '  :root:not([data-theme]) {',
    ...cssVars(dark, 'color', '    '),
    '    color-scheme: dark;',
    '  }',
    '}',
    '',
  ].join('\n');

  const lit = (o) => JSON.stringify(o, null, 2);
  const ts = [
    HEADER,
    `export const colors = {\n  light: ${lit(light).replace(/\n/g, '\n  ')},\n  dark: ${lit(dark).replace(/\n/g, '\n  ')},\n} as const;\n`,
    'export type ColorRole = keyof typeof colors.light;',
    'export type ThemeName = keyof typeof colors;\n',
    `export const typography = ${lit(fm.typography)} as const;\n`,
    `export const spacing = ${lit(spacing)} as const;\n`,
    `export const rounded = ${lit(rounded)} as const;\n`,
    '/** CSS variable reference for a color role, e.g. cssColor("primary") -> "var(--vm-color-primary)". */',
    'export const cssColor = (role: ColorRole): string => `var(--vm-color-${role})`;\n',
  ].join('\n');

  const tailwind = [
    HEADER,
    '/* Maps Tailwind utilities (bg-primary, text-muted, rounded-md, ...) to the theme variables. */',
    '@theme inline {',
    ...Object.keys(light).map((k) => `  --color-${k}: var(--vm-color-${k});`),
    ...Object.keys(rounded).filter((k) => k !== 'full').map((k) => `  --radius-${k}: var(--vm-radius-${k});`),
    '}',
    '',
  ].join('\n');

  return { css, ts, tailwind };
}

export function writeAll() {
  const { fm } = readDesign();
  const { css, ts, tailwind } = generate(fm);
  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(join(OUT_DIR, 'tailwind-theme.css'), tailwind);
  writeFileSync(join(OUT_DIR, 'tokens.css'), css);
  writeFileSync(join(OUT_DIR, 'tokens.ts'), ts);
  return { css, ts, tailwind };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeAll();
  console.log('tokens generated');
}
